#include <iostream>
#include <cstring>
using namespace std;

unsigned long long f[100][100], g[100];
unsigned long long i, j, k, n, h;

int main() {
    memset(f, 0, sizeof(f));
    memset(g, 0, sizeof(g));

    cin >> n >> h;

    g[0] = 1;
    f[0][0] = 1;

    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= i && j <= h; ++j) {
            for (k = 1; k <= i; ++k) {
                f[i][j] += f[k - 1][j - 1] * g[i - k];
                f[i][j] -= f[k - 1][j - 1] * f[i - k][j - 1];
                f[i][j] += g[k - 1] * f[i - k][j - 1];
            }
        }

        for (k = 1; k <= i; ++k)
            g[i] += g[k - 1] * g[i - k];

        f[i][0] = g[i];
    }

    cout << f[n][h] << '\n';
    return 0;
}

